    ('QB-PF2026-V01-IM-BANK-0055', 'd3aa6cf7e0a76318e691f7a9065940cc', '[{"type":"disease","slug":"MDMg7IaM7ZmU6riwL-ychOyepeq0gC_snITsi53rj4Qg7Jet66WYIOyniO2ZmCAoR0VSRCkgKEdhc3Ryb2Vzb3BoYWdlYWwgUmVmbHV4IERpc2Vhc2UpLm1k","title":"위식도 역류 질환 (GERD) (Gastroesophageal Reflux Disease)"}]'::jsonb, 'keep', '수개월의 속쓰림과 산 역류, 내시경상 역류성 식도염을 진단하는 문항이므로 GERD 문서가 직접 대응한다.', 'high', '["image-dependent"]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
