    ('QB-PF2026-V01-IM-BANK-0079', '0b1d6af48a557bde7a413a3c484577a6', '[{"type":"disease","slug":"MDQg64K067aE67mEL-uPheyEsSDso7zquLAg66eI67mEIChUaHlyb3RveGljIFBlcmlvZGljIFBhcmFseXNpcykubWQ","title":"독성 주기 마비 (Thyrotoxic Periodic Paralysis)"}]'::jsonb, 'keep', '갑상샘중독증 환자의 야간 양측 하지마비에서 저칼륨성 독성 주기마비를 의심하는 문항이므로 현재 문서가 정확하다.', 'high', '[]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0080', 'a532e491762d3d9c4a129ea45fc04e28', '[{"type":"disease","slug":"MDQg64K067aE67mEL-uLueuHqOuzkeyEsSDsvantjKXrs5Hspp0gKERpYWJldGljIE5lcGhyb3BhdGh5KS5tZA","title":"당뇨병성 콩팥병증 (Diabetic Nephropathy)"}]'::jsonb, 'keep', '당뇨병, 고혈압, 미세알부민뇨에서 신보호 항고혈압제를 선택하는 당뇨병성 콩팥병증 문항이므로 현재 연결은 정확하다. 다만 저장된 정답과 해설의 권고 약제가 서로 충돌한다.', 'high', '["answer-explanation-conflict"]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0081', '2f7a68e7d9ce2306d3fba74deb4957d7', '[{"type":"disease","slug":"MDQg64K067aE67mEL-u2gOqwkeyDgeyDmCDquLDriqXsoIDtlZjspp0gKEh5cG9wYXJhdGh5cm9pZGlzbSkubWQ","title":"부갑상샘 기능저하증 (Hypoparathyroidism)"}]'::jsonb, 'keep', '갑상샘 전절제 뒤 Trousseau 징후가 나타난 수술 후 부갑상샘 기능저하증 문항이므로 현재 문서가 정확하다. 저장된 정답은 저혈당이지만 해설과 임상상은 저칼슘혈증을 가리킨다.', 'high', '["answer-explanation-conflict"]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0082', '8722081df9fb57ff6f97b7158decd606', '[]'::jsonb, 'no-suitable-document', '성인의 골수 천자 부위를 묻는 술기 문항으로 특정 혈액질환과 연결되지 않는다. 혈액 대표문서는 지나치게 넓고 골수 천자·생검 문서가 카탈로그에 없다.', 'high', '["procedure-topic"]'::jsonb, '골수 천자 및 생검', 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0083', 'f94dd3cb43b57c437882e0ff857da7dd', '[]'::jsonb, 'no-suitable-document', '전이성 대장암 치료 중 발생한 말초신경병증으로 oxaliplatin을 식별하는 항암제 독성 문항이다. 종양 대표문서는 부정확하고 항암화학요법 유발 말초신경병증 문서가 없다.', 'high', '["drug-topic"]'::jsonb, '항암화학요법 유발 말초신경병증', 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0084', '2879411c6df71e969f956311d15f3a27', '[{"type":"disease","slug":"MDgg6rCQ7Je8L-2YuOykkeq1rOqwkOyGjOymnSAoTmV1dHJvcGVuaWEpLm1k","title":"호중구감소증 (Neutropenia)"}]'::jsonb, 'keep', '항암치료 뒤 중증 호중구감소와 발열이 생긴 환자의 경험적 항녹농균 항생제 치료를 묻는다. 발열성 호중구감소증 개별 문서는 없지만 현재 호중구감소증 문서가 가장 직접적이다.', 'high', '["exact-subtype-document-missing"]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0085', 'f6746a58b1c915ba331a55f7247dd522', '[]'::jsonb, 'no-suitable-document', 'VRE에 적용하는 접촉주의와 공기·비말주의를 구분하는 의료기관 감염관리 문항이다. 감염 대표문서는 지나치게 넓고 격리주의 개별 문서가 없다.', 'high', '[]'::jsonb, '의료관련감염의 표준주의 및 격리주의', 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0086', '9fb9e16093a60a7d25ebd60c43815a61', '[{"type":"disease","slug":"MDgg6rCQ7Je8L-unkOudvOumrOyVhCAoTWFsYXJpYSkubWQ","title":"말라리아 (Malaria)"}]'::jsonb, 'keep', '베트남 여행 뒤 주기적 발열·오한과 비장종대가 있는 환자에서 말초혈액도말로 말라리아를 진단하는 문항이므로 현재 문서가 정확하다.', 'high', '[]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0087', 'e9e6fc5c55942e6a8cc48ed58a293670', '[{"type":"disease","slug":"MDcg66WY66eI7Yuw7IqkL-yghOyLoCDtmY3rsJgg66Oo7ZG47IqkIChTeXN0ZW1pYyBMdXB1cyBFcnl0aGVtYXRvc3VzKS5tZA","title":"전신 홍반 루푸스 (Systemic Lupus Erythematosus)"}]'::jsonb, 'keep', '전신 증상, 발진, 관절통, 반복 유산과 신장 침범에서 이차 항인지질항체증후군을 동반한 SLE를 확인하는 항체를 묻는 문항이므로 현재 문서가 적절하다.', 'high', '[]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0088', '6437bf32559b494c3948bb373f97ef12', '[{"type":"disease","slug":"MDEg7Iic7ZmY6riwL-uwqeyLpOywqOuLqCAoQVYgYmxvY2spLm1k","title":"방실차단 (AV block)"}]'::jsonb, 'keep', '급성 심근경색 뒤 혈역학적 불안정과 P파-QRS 완전 해리를 보이는 완전 방실차단을 진단하는 문항이므로 현재 문서가 정확하다.', 'high', '["image-dependent"]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0089', 'cf74cae621120478bb1014d6e48887a1', '[{"type":"disease","slug":"MDcg66WY66eI7Yuw7IqkL-yXvOymneyEsSDqt7zrs5Hspp0gKEluZmxhbW1hdG9yeSBNeW9wYXRoeSkubWQ","title":"염증성 근병증 (Inflammatory Myopathy)"}]'::jsonb, 'keep', '피부 발진 없이 대칭성 근위부 근력저하, 연하곤란, 현저한 근효소 상승으로 다발근염을 진단하는 문항이다. 다발근염 개별 문서는 없고 염증성 근병증 문서가 가장 적절하다.', 'high', '["exact-subtype-document-missing"]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0090', 'b2f67f5fbe5df4f11ef15e643dcb1163', '[{"type":"disease","slug":"MDEg7Iic7ZmY6riwL-2YiOq0gOuvuOyjvOyLoOqyveyEsSDsi6Tsi6AgKFZhc292YWdhbCBTeW5jb3BlKS5tZA","title":"혈관미주신경성 실신 (Vasovagal Syncope)"}]'::jsonb, 'keep', '치과 치료와 혼잡한 환경 뒤 서맥·저혈압을 동반한 실신에서 하지 거상을 시행하는 혈관미주신경성 실신 문항이므로 현재 문서가 정확하다.', 'high', '[]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0091', '65e7862dd2b36e08f3b9a4c1f4b8e212', '[{"type":"disease","slug":"MDIg7Zi47Z2h6riwL-yynOyLnS5tZA","title":"천식"}]'::jsonb, 'replace', '메타콜린 유발검사 뒤 발생한 심한 기관지수축에 SABA를 투여하는 천식 문항이다. 현재 slug는 카탈로그 개편 전 경로이므로 현행 천식 정본 문서로 교체한다.', 'high', '["stale-current-slug"]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0092', '912e589cb7eb7ac7cef58c14b2fa5ca3', '[]'::jsonb, 'no-suitable-document', '동기화 심율동전환 뒤 심실세동으로 전환된 상황에서 비동기화 제세동 모드를 선택하는 장비·술기 문항이다. 부정맥 대표문서는 지나치게 넓고 전기적 심율동전환·제세동 문서가 없다.', 'high', '["image-dependent","procedure-topic"]'::jsonb, '전기적 심율동전환 및 제세동', 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0093', '8ad8b8b2593e49649dc532868c14e899', '[{"type":"disease","slug":"MDEg7Iic7ZmY6riwL-u5hO2bhOyEsSDsi6zqt7zrs5Hspp0gKEh5cGVydHJvcGhpYyBDYXJkaW9teW9wYXRoeSkubWQ","title":"비후성 심근병증 (Hypertrophic Cardiomyopathy)"}]'::jsonb, 'keep', '비후성 심근병증 환자의 급사 위험인자인 현저한 심실중격 비후를 묻는 문항이므로 현재 문서가 정확하다.', 'high', '[]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0095', 'cdabf3928f8b79689a9beb7dabdbdf53', '[{"type":"disease","slug":"MDEg7Iic7ZmY6riwL-yLrOuwqSDsobDrj5kt7IS464-ZIChBdHJpYWwgRmx1dHRlci1GaWJyaWxsYXRpb24pLm1k","title":"심방 조동-세동 (Atrial Flutter-Fibrillation)"}]'::jsonb, 'keep', '심방세동, 높은 뇌졸중 위험도, 좌심방 혈전이 있는 환자의 즉각적 헤파린 항응고를 묻는 문항이므로 현재 문서가 정확하다.', 'high', '["image-dependent"]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0096', '89a4cf0a4b0886d79a8ac315d7451110', '[{"type":"disease","slug":"MDEg7Iic7ZmY6riwL-uwnOyekeyEsSDsg4Hsi6zsi6TshLEg67mI66elIChQYXJveHlzbWFsIFN1cHJhdmVudHJpY3VsYXIgVGFjaHljYXJkaWEgKFBTVlQpLm1k","title":"발작성 상심실성 빈맥 (Paroxysmal Supraventricular Tachycardia (PSVT)"}]'::jsonb, 'keep', '저혈압과 의식소실을 동반한 불안정 PSVT에서 동기화 심율동전환을 시행하는 문항이므로 현재 문서가 정확하다.', 'high', '["image-dependent"]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0097', '5aa48d1230b2f6c38f2792e2ebff0085', '[{"type":"disease","slug":"MDEg7Iic7ZmY6riwL-uMgOuPmeunpe2MkOuniSDtmJHssKkgKEFvcnRpYyBTdGVub3NpcykubWQ","title":"대동맥판막 협착 (Aortic Stenosis)"}]'::jsonb, 'keep', '우상흉골연 수축기 잡음과 심도자 압력차로 대동맥판막 협착을 진단하는 문항이므로 현재 문서가 정확하다.', 'high', '["image-dependent"]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0098', '2caf5563a8c44418fd3a66651585725c', '[{"type":"disease","slug":"MDEg7Iic7ZmY6riwL-yasOyLrOyLpCDqsr3sg4kgKFJWIEluZmFyY3QpLm1k","title":"우심실 경색 (RV Infarct)"}]'::jsonb, 'keep', '하벽 심근경색과 저혈압을 보이는 우심실 경색에서 전부하 확보를 위한 수액을 우선하는 문항이므로 현재 문서가 정확하다.', 'high', '["image-dependent"]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0099', 'fcd5df6c27fd2ed9753849963250f44f', '[{"type":"disease","slug":"MDEg7Iic7ZmY6riwL-qzoO2YiOyVleyEsSDsnITquLAgKEh5cGVydGVuc2l2ZSBDcmlzaXMpLm1k","title":"고혈압성 위기 (Hypertensive Crisis)"}]'::jsonb, 'keep', '중증 고혈압, 경련·의식저하, 유두부종으로 고혈압성 응급을 진단하고 정주 혈압강하제를 선택하는 문항이므로 현재 문서가 정확하다.', 'high', '[]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0100', '65e9b78f7295e48ba5c0a7dc2e78ec69', '[{"type":"disease","slug":"MjAg67mE64eo6riw6rO8L-yWkeyEsSDsoITrpr3sg5gg67mE64yA7KadIChCZW5pZ24gUHJvc3RhdGljIEh5cGVycGxhc2lhKS5tZA","title":"양성 전립샘 비대증 (Benign Prostatic Hyperplasia)"}]'::jsonb, 'keep', '만성 하부요로증상 뒤 급성 요폐와 폐쇄성 급성 신손상이 발생한 BPH 환자에서 도뇨관 삽입을 묻는 문항이므로 현재 문서가 적절하다.', 'high', '[]'::jsonb, null, 'phase2-linked-internal-0051-0100.json'),
    ('QB-PF2026-V01-IM-BANK-0101', '097b6083f39e8eff9007c777b103d18b', '[{"type":"disease","slug":"MDMg7IaM7ZmU6riwL-ychOyepeq0gC_shozsnqUg7Y-Q7IeEIChTbWFsbCBCb3dlbCBPYnN0cnVjdGlvbikubWQ","title":"소장 폐쇄 (Small Bowel Obstruction)"}]'::jsonb, 'keep', '복부팽만과 반복 구토로 심한 탈수가 생긴 기계적 소장폐쇄에서 등장성 수액 소생을 우선하는 문항이므로 현재 문서가 정확하다.', 'high', '[]'::jsonb, null, 'phase2-linked-internal-0051-0100.json')
),
prepared as (
  select
    c.id,
    c.payload,
    c.index_data,
    v.action,
    v.rationale,
    v.confidence,
    v.flags,
    v.needed_document,
    v.manifest,
    coalesce((
      select jsonb_agg(document)
      from jsonb_array_elements(coalesce(c.payload->'relatedDocuments', '[]'::jsonb)) document
      where document->>'type' = 'drug'
    ), '[]'::jsonb) || v.proposed_documents as final_documents,
    coalesce((
      select jsonb_agg(document->>'slug')
      from jsonb_array_elements(v.proposed_documents) document
      where document->>'type' = 'disease'
    ), '[]'::jsonb) as final_disease_slugs,
    coalesce((
      select jsonb_agg(document->>'title')
      from jsonb_array_elements(v.proposed_documents) document
      where document->>'type' = 'disease'
    ), '[]'::jsonb) as final_disease_terms,
    coalesce((
      select jsonb_agg(document->>'slug')
      from jsonb_array_elements(v.proposed_documents) document
      where document->>'type' = 'cc'
    ), '[]'::jsonb) as final_cc_slugs
  from public.private_qbank_canonical_items c
  join review_values v on v.id = c.id
  where md5(c.payload::text) = v.payload_hash
),
updated as (
  update public.private_qbank_canonical_items c
  set
    payload = c.payload || jsonb_build_object(
      'relatedDocuments', p.final_documents,
      'relatedDiseaseSlugs', p.final_disease_slugs,
      'relatedDiseaseTerms', p.final_disease_terms,
      'relatedCcSlugs', p.final_cc_slugs,
      'linkReview', jsonb_strip_nulls(jsonb_build_object(
        'status', case
          when p.action = 'no-suitable-document' then 'codex-semantic-reviewed-no-suitable-document'
          when p.action = 'needs-review' then 'codex-semantic-review-pending'
          else 'codex-semantic-reviewed'
        end,
        'method', 'question-answer-explanation-review',
        'reviewVersion', '2026-09-22-v1',
        'reviewedAt', '2026-09-22T09:49:05.743Z',
        'action', p.action,
        'reason', p.rationale,
        'confidence', p.confidence,
        'flags', p.flags,
        'neededDocument', p.needed_document,
        'manifest', p.manifest,
        'previous', jsonb_build_object(
          'relatedDocuments', coalesce(c.payload->'relatedDocuments', '[]'::jsonb),
          'relatedDiseaseSlugs', coalesce(c.payload->'relatedDiseaseSlugs', '[]'::jsonb),
          'relatedDiseaseTerms', coalesce(c.payload->'relatedDiseaseTerms', '[]'::jsonb),
          'relatedCcSlugs', coalesce(c.payload->'relatedCcSlugs', '[]'::jsonb),
          'linkReview', coalesce(c.payload->'linkReview', '{}'::jsonb)
        )
      ))
    ),
    index_data = coalesce(c.index_data, '{}'::jsonb) || jsonb_build_object(
      'relatedDiseaseSlugs', p.final_disease_slugs,
      'relatedCcSlugs', p.final_cc_slugs
    )
  from prepared p
  where c.id = p.id
  returning c.id
)
select jsonb_build_object(
  'requested', (select count(*) from review_values),
  'updated', (select count(*) from updated),
  'conflicts', coalesce((
    select jsonb_agg(v.id order by v.id)
    from review_values v
    left join updated u on u.id = v.id
    where u.id is null
  ), '[]'::jsonb)
) as result;

commit;
